import{_ as i,o as l,c as n,a2 as t}from"./chunks/framework.DpXDHk3d.js";const p=JSON.parse('{"title":"14.4 配电线路与电能表接线实操","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-4-pei-dian-xian-lu-yu-dian-neng-biao-jie-xian-shi-cao.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-4-pei-dian-xian-lu-yu-dian-neng-biao-jie-xian-shi-cao.md","lastUpdated":1793096070000}'),o={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-4-pei-dian-xian-lu-yu-dian-neng-biao-jie-xian-shi-cao.md"};function s(e,a,r,c,h,g){return l(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="_14-4-配电线路与电能表接线实操" tabindex="-1">14.4 配电线路与电能表接线实操 <a class="header-anchor" href="#_14-4-配电线路与电能表接线实操" aria-label="Permalink to &quot;14.4 配电线路与电能表接线实操&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>配电箱接线、电能表接线是实操考核常见项目。这一节掌握照明线路、插座、单相和三相电能表的正确接法,接线要&quot;对号入座&quot;。</p><h2 id="一、配电线路-照明-插座-接线要点" tabindex="-1">一、配电线路(照明/插座)接线要点 <a class="header-anchor" href="#一、配电线路-照明-插座-接线要点" aria-label="Permalink to &quot;一、配电线路(照明/插座)接线要点&quot;">​</a></h2><ul><li><strong>火线(L)进开关</strong>,零线(N)进灯头;开关必须接在火线上;</li><li>插座:<strong>左零右火上接地</strong>(面对插座),三孔插座上孔接 PE;</li><li>灯具螺口:<strong>火线接中心触点,零线接螺纹</strong>;</li><li>导线分色规范:相线黄/绿/红、N 淡蓝、PE 黄绿双色;</li><li>接线牢固,铜导线压接到位,不外露。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进线: L ──► 开关 ──► 灯具 ──► N</span></span>
<span class="line"><span>       L ──► 插座左? 不,左孔N、右孔L</span></span>
<span class="line"><span>插座(面对): 左孔─N   右孔─L   上孔─PE</span></span></code></pre></div><h2 id="二、单相电能表-家用电度表-的接线" tabindex="-1">二、单相电能表(家用电度表)的接线 <a class="header-anchor" href="#二、单相电能表-家用电度表-的接线" aria-label="Permalink to &quot;二、单相电能表(家用电度表)的接线&quot;">​</a></h2><p>常用<strong>直接接入</strong>方式(小电流、直接测量):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进线: L ──► 电能表 1(相线进)──► 2(相线出)──► 负载</span></span>
<span class="line"><span>       N ──► 电能表 3(零线进)──► 4(零线出)──► 负载</span></span></code></pre></div><p>以常见单相表(1、3 进,2、4 出)为例:</p><ul><li>表尾 1、3 接<strong>进线</strong>(1 火、3 零);</li><li>表尾 2、4 接<strong>出线</strong>(2 火、4 零);</li><li>电能表<strong>接线顺序不能反</strong>:火线必须经电流线圈,零线经电压回路。</li></ul><blockquote><p>⚠️ 判断题常考:<strong>单相电能表接线时火线、零线进出不能颠倒</strong>(接反会使表不走或计量错误)。</p></blockquote><h2 id="三、三相电能表的接线" tabindex="-1">三、三相电能表的接线 <a class="header-anchor" href="#三、三相电能表的接线" aria-label="Permalink to &quot;三、三相电能表的接线&quot;">​</a></h2><ul><li><strong>三相四线有功电能表</strong>有 11 个端子(或按说明书):三组电流、电压分别对应 L1、L2、L3、N;</li><li>电流线圈<strong>串接</strong>在相线中,电压线圈<strong>并接</strong>在相线对 N 之间;</li><li>常用<strong>互感器接入</strong>时,电流互感器 TA 串接,注意<strong>同名端</strong>和极性;</li><li>接线后核对<strong>表号和相序</strong>,不能接错相。</li></ul><blockquote><p>💡 记住:<strong>电流线圈串联、电压线圈并联</strong>,这是电能表接线的总原则。</p></blockquote><h2 id="四、接线检查与试车" tabindex="-1">四、接线检查与试车 <a class="header-anchor" href="#四、接线检查与试车" aria-label="Permalink to &quot;四、接线检查与试车&quot;">​</a></h2><ul><li>接完后对照原理图/表尾接线图<strong>逐点核对</strong>;</li><li>检查有无<strong>短路</strong>(用万用表测进线端通断);</li><li>送电后观察<strong>表盘是否走字</strong>,方向是否正确(三相表不得反转);</li><li>接线端子<strong>压紧、无松动</strong>,表箱接地良好。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 插座左零右火、上孔接地;开关接火线。</li><li>✅ 单相电能表:1、3 进(火、零),2、4 出(火、零),进出不能反。</li><li>✅ 电能表:电流线圈<strong>串联</strong>、电压线圈<strong>并联</strong>。</li><li>✅ 接完核对、检查短路,送电看走字。</li><li>⚠️ 易混点:单相表进出线序、三相表相序——接错会计量错误或表不转。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>配电线路:火进开关、左零右火、螺口灯头接线规范。</li><li>电能表:单相按进线出线对号,三相按相序接线。</li><li>电流串、电压并,接完必查、送电看表。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)面对插座,左孔接零线、右孔接火线,三孔插座上孔接地。( )</li><li>(判断)单相电能表接线时,火线和零线的进出可以任意颠倒。( )</li><li>(单选)电能表接线的基本原则是()。 A. 电流线圈串联、电压线圈并联　B. 电流线圈并联、电压线圈串联 C. 全部串联　D. 全部并联</li><li>(判断)电能表接线完成后,送电应观察表盘是否正常走字。( )</li><li>(判断)照明开关必须接在火线上。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。左零右火上接地。</li><li><strong>×</strong>。火线零线进出不能颠倒。</li><li><strong>A</strong>。电流线圈串联、电压线圈并联。</li><li><strong>√</strong>。送电看走字、看方向。</li><li><strong>√</strong>。开关接火线是安全底线。</li></ol></details>`,24)])])}const u=i(o,[["render",s]]);export{p as __pageData,u as default};
